    /**
     * @method
     * @name backpack#withdraw
     * @description make a withdrawal
     * @see https://docs.backpack.exchange/#tag/Capital/operation/request_withdrawal
     * @param {string} code unified currency code
     * @param {float} amount the amount to withdraw
     * @param {string} address the address to withdraw to
     * @param {string} tag
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {string} params.network the network to withdraw on (mandatory)
     * @returns {object} a [transaction structure]{@link https://docs.ccxt.com/?id=transaction-structure}
     */
    public java.util.concurrent.CompletableFuture<io.github.ccxt.types.Transaction> withdraw(Object code, Object amount, Object address, Object... optionalArgs)
    {

        return java.util.concurrent.CompletableFuture.supplyAsync(() -> {

            Object tag = Helpers.getArg(optionalArgs, 0, null);
            Object parameters = Helpers.getArg(optionalArgs, 1, new java.util.HashMap<String, Object>() {{}});
            if (Helpers.isTrue(Helpers.isEqual(this.markets, null)))
            {
                (this.loadMarkets()).join();
            }
            Object currency = this.currency(code);
            Object request = new java.util.HashMap<String, Object>() {{
                put( "symbol", Helpers.GetValue(currency, "id") );
                put( "quantity", Backpack.this.numberToString(amount) );
                put( "address", address );
            }};
            if (Helpers.isTrue(!Helpers.isEqual(tag, null)))
            {
                Helpers.addElementToObject(request, "clientId", tag); // memo or tag
            }
            var networkCodequeryVariable = this.handleNetworkCodeAndParams(parameters);
            var networkCode = ((java.util.List<Object>) networkCodequeryVariable).get(0);
            var query = ((java.util.List<Object>) networkCodequeryVariable).get(1);
            Object networkId = this.networkCodeToId(networkCode, Helpers.GetValue(currency, "code"));
            if (Helpers.isTrue(Helpers.isEqual(networkId, null)))
            {
                throw new BadRequest((String)Helpers.add(this.id, " withdraw() requires a network parameter")) ;
            }
            Helpers.addElementToObject(request, "blockchain", networkId);
            Object response = (this.privatePostWapiV1CapitalWithdrawals(this.extend(request, query))).join();
            return this.parseTransaction(response, currency);
        }).thenApply(io.github.ccxt.TypedCores::toTransaction);

    }

    public Object parseTransaction(Object transaction, Object... optionalArgs)
    {
        //
        // fetchDeposits
        //     [
        //         {
        //             "createdAt": "2025-07-23T13:55:54.267",
        //             "fiatAmount": null,
        //             "fiatCurrency": null,
        //             "fromAddress": "0x2e3ab3e88a7dbdc763aadf5b28c18fb085af420a",
        //             "id": 6695353,
        //             "institutionBic": null,
        //             "platformMemo": null,
        //             "quantity": "120",
        //             "source": "ethereum",
        //             "status": "confirmed",
        //             "symbol": "USDC",
        //             "toAddress": "0xfBe7CbfCde93c8a4204a4be6B56732Eb32690170",
        //             "transactionHash": "0x58edaac415398d617b34c6673fffcaf0024990d5700565030119db5cbf3765d1"
        //         }
        //     ]
        //
        // withdraw
        //     {
        //         "accountIdentifier": null,
        //         "bankIdentifier": null,
        //         "bankName": null,
        //         "blockchain": "Ethereum",
        //         "clientId": null,
        //         "createdAt": "2025-08-13T19:27:13.817",
        //         "fee": "3",
        //         "fiatFee": null,
        //         "fiatState": null,
        //         "fiatSymbol": null,
        //         "id": 5479929,
        //         "identifier": null,
        //         "isInternal": false,
        //         "providerId": null,
        //         "quantity": "10",
        //         "status": "pending",
        //         "subaccountId": null,
        //         "symbol": "USDC",
        //         "toAddress": "0x0ad42b8e602c2d3d475ae52d678cf63d84ab2749",
        //         "transactionHash": null,
        //         "triggerAt": null
        //     }
        //
        // fetchWithdrawals
        //     [
        //         {
        //             "accountIdentifier": null,
        //             "bankIdentifier": null,
        //             "bankName": null,
        //             "blockchain": "Ethereum",
        //             "clientId": null,
        //             "createdAt": "2025-08-13T19:27:13.817",
        //             "fee": "3",
        //             "fiatFee": null,
        //             "fiatState": null,
        //             "fiatSymbol": null,
        //             "id": 5479929,
        //             "identifier": null,
        //             "isInternal": false,
        //             "providerId": null,
        //             "quantity": "10",
        //             "status": "confirmed",
        //             "subaccountId": null,
        //             "symbol": "USDC",
        //             "toAddress": "0x0ad42b8e602c2d3d475ae52d678cf63d84ab2749",
        //             "transactionHash": "0x658b6d082af4afa0d3cf85caf344ff7c19d980117726bf193b00d8850f8746a1",
        //             "triggerAt": null
        //         }
        //     ]
        //
        Object currency = Helpers.getArg(optionalArgs, 0, null);
        Object status = this.parseTransactionStatus(this.safeString(transaction, "status"));
        Object id = this.safeString(transaction, "id");
        Object txid = this.safeString(transaction, "transactionHash");
        Object coin = this.safeString(transaction, "symbol");
        Object code = this.safeCurrencyCode(coin, currency);
        Object timestamp = this.parse8601(this.safeString(transaction, "createdAt"));
        Object amount = this.safeNumber(transaction, "quantity");
        Object networkId = this.safeStringLower2(transaction, "source", "blockchain");
        Object network = this.networkIdToCode(networkId, code);
        Object addressTo = this.safeString(transaction, "toAddress");
        Object addressFrom = this.safeString(transaction, "fromAddress");
        Object tag = this.safeString(transaction, "platformMemo");
        Object feeCost = this.safeNumber(transaction, "fee");
        Object intern = this.safeBool(transaction, "isInternal", false);
        Object fee = null;
        if (Helpers.isTrue(!Helpers.isEqual(feeCost, null)))
        {
            final Object finalFeeCost = feeCost;
            fee = new java.util.HashMap<String, Object>() {{
                put( "cost", finalFeeCost );
                put( "currency", code );
            }};
        }
        final Object finalFee = fee;
        return new java.util.HashMap<String, Object>() {{
            put( "info", transaction );
            put( "id", id );
            put( "txid", txid );
            put( "timestamp", timestamp );
            put( "datetime", Backpack.this.iso8601(timestamp) );
            put( "network", network );
            put( "address", null );
            put( "addressTo", addressTo );
            put( "addressFrom", addressFrom );
            put( "tag", tag );
            put( "tagTo", null );
            put( "tagFrom", null );
            put( "type", null );
            put( "amount", amount );
            put( "currency", code );
            put( "status", status );
            put( "updated", null );
            put( "internal", intern );
            put( "comment", null );
            put( "fee", finalFee );
        }};
    }

    public Object parseTransactionStatus(Object status)
    {
        Object statuses = new java.util.HashMap<String, Object>() {{
            put( "cancelled", "cancelled" );
            put( "confirmed", "ok" );
            put( "declined", "declined" );
            put( "expired", "expired" );
            put( "initiated", "initiated" );
            put( "pending", "pending" );
            put( "refunded", "refunded" );
            put( "information required", "pending" );
        }};
        return this.safeString(statuses, status, status);
    }

