    public Object parseOrder(Object order, Object... optionalArgs)
    {
        //
        //     {
        //         "clientId": null,
        //         "createdAt": 1753624283415,
        //         "executedQuantity": "0.001",
        //         "executedQuoteQuantity": "3.81428",
        //         "id": "4227701917",
        //         "orderType": "Market",
        //         "quantity": "0.001",
        //         "quoteQuantity": "3.82",
        //         "reduceOnly": null,
        //         "relatedOrderId": null,
        //         "selfTradePrevention": "RejectTaker",
        //         "side": "Bid",
        //         "status": "Filled",
        //         "stopLossLimitPrice": null,
        //         "stopLossTriggerBy": null,
        //         "stopLossTriggerPrice": null,
        //         "strategyId": null,
        //         "symbol": "ETH_USDC",
        //         "takeProfitLimitPrice": null,
        //         "takeProfitTriggerBy": null,
        //         "takeProfitTriggerPrice": null,
        //         "timeInForce": "GTC",
        //         "triggerBy": null,
        //         "triggerPrice": null,
        //         "triggerQuantity": null,
        //         "triggeredAt": null
        //     }
        //
        // fetchOpenOrders
        //     {
        //         "clientId": 123456789,
        //         "createdAt": 1753626206762,
        //         "executedQuantity": "0",
        //         "executedQuoteQuantity": "0",
        //         "id": "4228978331",
        //         "orderType": "Limit",
        //         "postOnly": true,
        //         "price": "3000",
        //         "quantity": "0.001",
        //         "reduceOnly": null,
        //         "relatedOrderId": null,
        //         "selfTradePrevention": "RejectTaker",
        //         "side": "Bid",
        //         "status": "New",
        //         "stopLossLimitPrice": null,
        //         "stopLossTriggerBy": null,
        //         "stopLossTriggerPrice": null,
        //         "strategyId": null,
        //         "symbol": "ETH_USDC",
        //         "takeProfitLimitPrice": null,
        //         "takeProfitTriggerBy": null,
        //         "takeProfitTriggerPrice": null,
        //         "timeInForce": "GTC",
        //         "triggerBy": null,
        //         "triggerPrice": null,
        //         "triggerQuantity": null,
        //         "triggeredAt": null
        //     }
        //
        // fetchOrders
        //     {
        //         "clientId": null,
        //         "createdAt": "2025-07-27T18:05:40.897",
        //         "executedQuantity": "0",
        //         "executedQuoteQuantity": "0",
        //         "expiryReason": null,
        //         "id": "4239996998",
        //         "orderType": "Limit",
        //         "postOnly": false,
        //         "price": "4500",
        //         "quantity": null,
        //         "quoteQuantity": null,
        //         "selfTradePrevention": "RejectTaker",
        //         "side": "Ask",
        //         "status": "Cancelled",
        //         "stopLossLimitPrice": null,
        //         "stopLossTriggerBy": null,
        //         "stopLossTriggerPrice": null,
        //         "strategyId": null,
        //         "symbol": "ETH_USDC",
        //         "systemOrderType": null,
        //         "takeProfitLimitPrice": null,
        //         "takeProfitTriggerBy": null,
        //         "takeProfitTriggerPrice": null,
        //         "timeInForce": "GTC",
        //         "triggerBy": null,
        //         "triggerPrice": "4300",
        //         "triggerQuantity": "0.001"
        //     }
        //
        Object market = Helpers.getArg(optionalArgs, 0, null);
        Object timestamp = this.safeInteger(order, "createdAt");
        Object timestamp2 = this.parse8601(this.safeString(order, "createdAt"));
        if (Helpers.isTrue(!Helpers.isEqual(timestamp2, null)))
        {
            timestamp = timestamp2;
        }
        Object id = this.safeString(order, "id");
        Object clientOrderId = this.safeString(order, "clientId");
        Object symbol = this.safeSymbol(this.safeString(order, "symbol"), market);
        Object type = this.safeStringLower(order, "orderType");
        Object timeInForce = this.safeString(order, "timeInForce");
        Object side = this.parseOrderSide(this.safeString(order, "side"));
        Object amount = this.safeString2(order, "quantity", "triggerQuantity");
        Object price = this.safeString(order, "price");
        Object cost = this.safeString(order, "executedQuoteQuantity");
        Object status = this.parseOrderStatus(this.safeString(order, "status"));
        Object triggerPrice = this.safeString(order, "triggerPrice");
        Object filled = this.safeString(order, "executedQuantity");
        Object reduceOnly = this.safeBool(order, "reduceOnly");
        Object postOnly = this.safeBool(order, "postOnly");
        Object stopLossPrice = this.safeString2(order, "stopLossLimitPrice", "stopLossTriggerPrice");
        Object takeProfitPrice = this.safeString2(order, "takeProfitLimitPrice", "takeProfitTriggerPrice");
        final Object finalTimestamp = timestamp;
        return this.safeOrder(new java.util.HashMap<String, Object>() {{
            put( "info", order );
            put( "id", id );
            put( "clientOrderId", clientOrderId );
            put( "timestamp", finalTimestamp );
            put( "datetime", Backpack.this.iso8601(finalTimestamp) );
            put( "lastTradeTimestamp", null );
            put( "symbol", symbol );
            put( "type", type );
            put( "timeInForce", timeInForce );
            put( "postOnly", postOnly );
            put( "reduceOnly", reduceOnly );
            put( "side", side );
            put( "price", price );
            put( "triggerPrice", triggerPrice );
            put( "stopLossPrice", stopLossPrice );
            put( "takeProfitPrice", takeProfitPrice );
            put( "amount", amount );
            put( "cost", cost );
            put( "average", null );
            put( "filled", filled );
            put( "remaining", null );
            put( "status", status );
            put( "fee", null );
            put( "trades", null );
        }}, market);
    }

